#include <stdio.h>
#include <stdint.h>

#define MAXN 100005

typedef struct {
    long long key;
    uint32_t pri;
    int cnt, sz, l, r;
} Node;

Node tr[MAXN];
int nodes = 0;
uint32_t seed = 2463534242u;

uint32_t rng(void) {
    seed ^= seed << 13;
    seed ^= seed >> 17;
    seed ^= seed << 5;
    return seed;
}

int sz(int t) {
    return t ? tr[t].sz : 0;
}

void upd(int t) {
    tr[t].sz = tr[t].cnt + sz(tr[t].l) + sz(tr[t].r);
}

int new_node(long long key) {
    ++nodes;
    tr[nodes].key = key;
    tr[nodes].pri = rng();
    tr[nodes].cnt = 1;
    tr[nodes].sz = 1;
    tr[nodes].l = 0;
    tr[nodes].r = 0;
    return nodes;
}

int rotate_right(int y) {
    int x = tr[y].l;
    tr[y].l = tr[x].r;
    tr[x].r = y;
    upd(y);
    upd(x);
    return x;
}

int rotate_left(int x) {
    int y = tr[x].r;
    tr[x].r = tr[y].l;
    tr[y].l = x;
    upd(x);
    upd(y);
    return y;
}

int insert(int t, long long key) {
    if (!t) return new_node(key);

    if (key == tr[t].key) {
        tr[t].cnt++;
        upd(t);
        return t;
    }

    if (key < tr[t].key) {
        tr[t].l = insert(tr[t].l, key);
        if (tr[tr[t].l].pri < tr[t].pri) {
            t = rotate_right(t);
        }
    } else {
        tr[t].r = insert(tr[t].r, key);
        if (tr[tr[t].r].pri < tr[t].pri) {
            t = rotate_left(t);
        }
    }

    upd(t);
    return t;
}

int count_le(int t, long long key) {
    int res = 0;
    while (t) {
        if (key < tr[t].key) {
            t = tr[t].l;
        } else {
            res += sz(tr[t].l) + tr[t].cnt;
            t = tr[t].r;
        }
    }
    return res;
}

int main(void) {
    int N;
    if (scanf("%d", &N) != 1) return 0;

    int root = 0;
    int prev_penalty = 0;

    for (int i = 0; i < N; i++) {
        long long x, y;
        scanf("%lld %lld", &x, &y);

        long long X = x + prev_penalty;
        long long Y = y + prev_penalty;
        long long dist = X * X + Y * Y;

        int penalty = count_le(root, dist);
        printf("%d\n", penalty);

        root = insert(root, dist);
        prev_penalty = penalty;
    }

    return 0;
}
